window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51c18b880c12fcce"]={"versions": [{"id": "FIG-51c18b880c12fcce", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Scheduling-Diagramm im Kontext des AUTOSAR Operating System (OS). Dargestellt ist das Zeitverhalten und die Ausführungsabfolge preemptiver Tasks (Prioritäten Low und High) entlang einer diskreten Zeitachse zur Definition grundlegender Echtzeit- und Scheduling-Begriffe.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Task Low: Niedrig priorisierter Task mit Voremption.\n</li><li>Task High: Hoch priorisierter, unterbrechender Task.\n</li><li>Zeitachse: Diskrete Zeiteinheiten von t = 0 bis t = 24.\n</li><li>Zeitmetriken und Markierungen: Inter-arrival time, Deadline, Response Time, Execution Time, Task-Aktivierungszeitpunkte sowie Task-Terminierung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>t = 0: Aktivierung von Task Low („Task LOW activated“).\n</li><li>t = 0 bis t = 2: Ausführung von Task High (Dauer: 2 Zeiteinheiten); Task Low ist bereit, wird jedoch verdrängt.\n</li><li>t = 2 bis t = 6: Task High ist inaktiv; Task Low führt aus (4 Zeiteinheiten).\n</li><li>t = 6 bis t = 8: Task High wird erneut aktiv und unterbricht Task Low (2 Zeiteinheiten).\n</li><li>t = 8 bis t = 10: Task Low führt weiter aus (2 Zeiteinheiten).\n</li><li>t = 10 bis t = 12: Task High unterbricht Task Low erneut (2 Zeiteinheiten).\n</li><li>t = 12 bis t = 16: Task Low führt den verbleibenden Teil aus (4 Zeiteinheiten).\n</li><li>t = 16: Task Low beendet die Ausführung („Task LOW terminates“). Die akkumulierte Execution Time von Task Low beträgt 10 Zeiteinheiten (4 + 2 + 4), die Response Time reicht von t = 0 bis t = 16.\n</li><li>t = 18: Relative Deadline von Task Low.\n</li><li>t = 20: Ende der Inter-Arrival Time; erneute Aktivierung von Task Low („Task LOW activated again“) mit Ausführung ab t = 20.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild spezifiziert die Basiskonzepte für AUTOSAR-OS-Timing-Analysen. Es definiert visuell die Abgrenzung zwischen reiner Ausführungszeit (Execution Time / WCET) und Antwortzeit (Response Time) unter Voremption durch höher priorisierte Tasks. Zudem verdeutlicht es das Einhalten von Fristen (Deadline) und die minimale bzw. periodische Aktivierungsdistanz (Inter-arrival time / Time Frame).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7502e0e20c9943cd", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Kombiniertes Begriffs- und Timing-Spezifikationsdokument des AUTOSAR Operating System (OS). Enthält eine tabellarische Definition zentraler OS-Termini (Schedule-Table-Synchronisation, Zähler, Ausführungszeiten, Zugriffsarten und Schutzelemente) sowie ein untergeordnetes Timing- und Scheduling-Diagramm zur Veranschaulichung von Task-Ausführungen unter Priorisierung und Voremption.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Glossartabelle: Begriffe und Definitionen für „Synchronization of schedule tables with a synchronization counter“, „Synchronization Counter“, „Time Frame“, „Trusted Function“, „Worst case execution time (WCET)“ und „Write access“.\n</li><li>Task Low: Niedrig priorisierter Task.\n</li><li>Task High: Hoch priorisierter Task.\n</li><li>Diskrete Zeitachse: Zeiteinheiten 0 bis 24.\n</li><li>Timing-Kenngrößen: Inter-arrival time, Deadline, Response Time, Execution Time.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>t = 0: Gleichzeitige Aktivierung beider Tasks („Task HIGH and Task LOW activated“). Aufgrund höherer Priorität startet Task High unmittelbar.\n</li><li>t = 0 bis t = 2: Task High belegt die CPU (2 Zeiteinheiten); Task Low verharrt im Zustand bereit.\n</li><li>t = 2 bis t = 6: Task Low führt aus (4 Zeiteinheiten).\n</li><li>t = 6 bis t = 8: Task High unterbricht Task Low (2 Zeiteinheiten).\n</li><li>t = 8 bis t = 10: Task Low führt aus (2 Zeiteinheiten).\n</li><li>t = 10 bis t = 12: Task High unterbricht Task Low (2 Zeiteinheiten).\n</li><li>t = 12 bis t = 16: Task Low führt zu Ende (4 Zeiteinheiten).\n</li><li>t = 16: Terminierung von Task Low („Task LOW terminates“). Die Gesamtrechenzeit (Execution Time) beträgt 10 Zeiteinheiten, die Response Time 16 Zeiteinheiten.\n</li><li>t = 18: Deadline von Task Low.\n</li><li>t = 20: Ablauf der Inter-arrival time und erneute Aktivierung von Task Low („Task LOW activated again“).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Terminologie und Timing-Parameter für das AUTOSAR OS. Neben den Zeitmetriken für Task-Scheduling und Verdrängung (Execution Time, Response Time, Deadline, Inter-arrival time / Time Frame) werden formale Kriterien für Schedule-Table-Synchronisation (Präzisionsschwellwert gegenüber Synchronisationszählern), Trusted Functions sowie Speicherzugriffsdefinitionen (Write Access inklusive Nebeneffekten) festgelegt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-278c220c13228589", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Kombiniertes Begriffs- und Timing-Spezifikationsdokument des AUTOSAR Operating System (OS). Enthält eine tabellarische Definition zentraler OS-Termini (Schedule-Table-Synchronisation, Zähler, Ausführungszeiten, Zugriffsarten und Schutzelemente) sowie ein untergeordnetes Timing- und Scheduling-Diagramm zur Veranschaulichung von Task-Ausführungen unter Priorisierung und Voremption.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Glossartabelle: Begriffe und Definitionen für „Synchronization of schedule tables with a synchronization counter“, „Synchronization Counter“, „Time Frame“, „Trusted Function“, „Worst case execution time (WCET)“ und „Write access“.\n</li><li>Task Low: Niedrig priorisierter Task.\n</li><li>Task High: Hoch priorisierter Task.\n</li><li>Diskrete Zeitachse: Zeiteinheiten 0 bis 24.\n</li><li>Timing-Kenngrößen: Inter-arrival time, Deadline, Response Time, Execution Time.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>t = 0: Gleichzeitige Aktivierung beider Tasks („Task HIGH and Task LOW activated“). Aufgrund höherer Priorität startet Task High unmittelbar.\n</li><li>t = 0 bis t = 2: Task High belegt die CPU (2 Zeiteinheiten); Task Low verharrt im Zustand bereit.\n</li><li>t = 2 bis t = 6: Task Low führt aus (4 Zeiteinheiten).\n</li><li>t = 6 bis t = 8: Task High unterbricht Task Low (2 Zeiteinheiten).\n</li><li>t = 8 bis t = 10: Task Low führt aus (2 Zeiteinheiten).\n</li><li>t = 10 bis t = 12: Task High unterbricht Task Low (2 Zeiteinheiten).\n</li><li>t = 12 bis t = 16: Task Low führt zu Ende (4 Zeiteinheiten).\n</li><li>t = 16: Terminierung von Task Low („Task LOW terminates“). Die Gesamtrechenzeit (Execution Time) beträgt 10 Zeiteinheiten, die Response Time 16 Zeiteinheiten.\n</li><li>t = 18: Deadline von Task Low.\n</li><li>t = 20: Ablauf der Inter-arrival time und erneute Aktivierung von Task Low („Task LOW activated again“).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Terminologie und Timing-Parameter für das AUTOSAR OS. Neben den Zeitmetriken für Task-Scheduling und Verdrängung (Execution Time, Response Time, Deadline, Inter-arrival time / Time Frame) werden formale Kriterien für Schedule-Table-Synchronisation (Präzisionsschwellwert gegenüber Synchronisationszählern), Trusted Functions sowie Speicherzugriffsdefinitionen (Write Access inklusive Nebeneffekten) festgelegt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-51c18b880c12fcce", "to": "FIG-7502e0e20c9943cd", "fr": "R3.0.7", "tr": "R3.1.5", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einbettung einer normativen Glossartabelle über dem Zeitablaufdiagramm mit Definitionen zu „Synchronization of schedule tables with a synchronization counter“, „Synchronization Counter“, „Time Frame“, „Trusted Function“, „Worst case execution time (WCET)“ und „Write access“.\n</li><li>Beschriftung bei t=0 im Zeitablaufdiagramm: Ausweitung von „Task LOW activated“ zu „Task HIGH and Task LOW activated“.\n</li></ul>"}, {"from": "FIG-7502e0e20c9943cd", "to": "FIG-278c220c13228589", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
